#!/bin/sh
# Writes the self-hosting secrets to an env file (default .env) unless it
# already exists, so `make up` works from a clean checkout and no two
# installations share a password.
set -eu

file=${1:-.env}
if [ -e "$file" ]; then
	exit 0
fi

secret() { openssl rand -hex "$1"; }

umask 077
cat >"$file" <<ENV
# Self-hosting configuration for compose.yaml, generated by \`make up\`.
# Keep this file private, and keep it: the passwords are stored in the
# PostgreSQL volume when it is created, and the master key encrypts Zitadel's
# data.

POSTGRES_PASSWORD=$(secret 24)
WA_OWNER_PASSWORD=$(secret 24)
WA_APP_PASSWORD=$(secret 24)
WA_READER_PASSWORD=$(secret 24)
ZITADEL_DB_PASSWORD=$(secret 24)
# Exactly 32 characters.
ZITADEL_MASTERKEY=$(secret 16)
# The first Zitadel administrator, "admin", in the console at
# http://AUTH_DOMAIN:AUTH_PORT/ui/console.
ZITADEL_ADMIN_PASSWORD=Wa1!$(secret 12)
GRAFANA_ADMIN_PASSWORD=$(secret 12)

# Where Zitadel is reached, by the browser and by the app. Inside Compose,
# AUTH_DOMAIN resolves to the Zitadel container; *.localhost resolves to this
# machine in browsers and curl.
#AUTH_DOMAIN=auth.localhost
#AUTH_PORT=8081
# The audience tokens must carry: the ID of the Zitadel project that Wallet
# Accountant's users sign in to. zitadel-setup creates the project with this
# ID on the first \`make up\`.
#OIDC_AUDIENCE=wallet-accountant
#APP_PORT=8080
#GRAFANA_PORT=3000
ENV
echo "Wrote $file with new secrets."
